parameters.jsCode:
// Deterministic checks. The agent's output is a proposal; nothing here trusts it
// without comparing against config or a fresh read of the system of record.
const cfg = $('Config').first().json;
const out = $('EMPI resolution agent').item.json.output ?? null;
const reasons = [];
if (!out) reasons.push('agent_produced_no_valid_output');
if (out && !(typeof out.confidence === 'number' && out.confidence >= cfg.min_confidence)) {
  reasons.push('confidence ' + out?.confidence + ' below ' + cfg.min_confidence);
}

const req = $('Normalize match task').item.json;
// Fresh read of both records: { a: {...}, b: {...} }, each with its history entry ids.
const A = $json.a ?? {};
const B = $json.b ?? {};
const d = out?.decision;
const noop = d === 'different_people';
const historyIds = new Set([...(A.history ?? []), ...(B.history ?? [])].map((h) => String(h.id)));
const explained = (attr) => (out?.conflicts_explained ?? []).some((c) => c.attribute === attr && historyIds.has(String(c.supporting_source)));
const agentSays = (attr) => (out?.evidence ?? []).find((e) => e.attribute === attr)?.comparison;
const day = (v) => (v ? String(v).slice(0, 10) : null);

for (const [label, r, id] of [['A', A, req.record_a], ['B', B, req.record_b]]) {
  if (String(r.record_id) !== id) reasons.push('record ' + label + ' could not be re-read');
  else if (r.status !== 'active' || r.merged_into) reasons.push('record ' + id + ' is ' + (r.merged_into ? 'already merged into ' + r.merged_into : r.status));
}
if (d === 'uncertain') reasons.push('agent is uncertain; a data steward decides');
if (d === 'same_person') {
  if (!(out.match_score >= cfg.min_match_score)) reasons.push('match score ' + out.match_score + ' below ' + cfg.min_match_score);
  // Hard identifiers, recomputed from the records. A conflict blocks the merge unless a cited history entry explains it.
  const dobA = day(A.birth_date), dobB = day(B.birth_date);
  const dobConflict = dobA && dobB && dobA !== dobB;
  if (dobConflict && !explained('birth_date')) reasons.push('dates of birth differ with no cited history entry explaining it');
  if (dobConflict && agentSays('birth_date') === 'match') reasons.push('agent says dates of birth match, the records differ');
  const sexConflict = A.sex && B.sex && !['unknown', 'other'].includes(A.sex) && !['unknown', 'other'].includes(B.sex) && A.sex !== B.sex;
  if (sexConflict && !explained('sex')) reasons.push('administrative sex differs with no cited history entry explaining it');
  if (sexConflict && agentSays('sex') === 'match') reasons.push('agent says sex matches, the records differ');
  for (const sys of cfg.hard_identifier_systems) {
    const va = (A.identifiers ?? []).find((i) => i.system === sys)?.value;
    const vb = (B.identifiers ?? []).find((i) => i.system === sys)?.value;
    if (va && vb && va !== vb) reasons.push('records carry different ' + sys.split('/').pop() + ' values; never merged');
  }
  if ((A.encounter_overlaps ?? []).includes(req.record_b) || (B.encounter_overlaps ?? []).includes(req.record_a)) reasons.push('the records have overlapping inpatient stays');
  const ev = out.evidence ?? [];
  if (!ev.some((e) => e.comparison === 'match')) reasons.push('no matching attribute cited');
  const bad = ev.filter((e) => !String(e.source).startsWith(req.record_a) && !String(e.source).startsWith(req.record_b) && !historyIds.has(String(e.source)));
  if (bad.length) reasons.push(bad.length + ' evidence entries cite something other than these two records or their history');
}

const survivor = out?.surviving_record === 'b' ? req.record_b : req.record_a;
const retired = survivor === req.record_a ? req.record_b : req.record_a;
const action = { type: 'merge', task_id: req.task_id, survivor_id: survivor, retired_id: retired, match_score: out?.match_score ?? null, evidence: out?.evidence ?? [], conflicts_explained: out?.conflicts_explained ?? [] };
// EMPI ids and attribute names only: no identifier values in Slack.
const allEv = out?.evidence ?? [];
const summary = noop
  ? 'EMPI task ' + req.task_id + ': ' + req.record_a + ' and ' + req.record_b + ' are different people. No merge.'
  : 'EMPI task ' + req.task_id + ': merge *' + retired + '* into *' + survivor + '*\n'
    + 'Score ' + out?.match_score + ' · ' + allEv.filter((e) => e.comparison === 'match').length + ' attributes match, '
    + allEv.filter((e) => e.comparison === 'conflict').length + ' conflict (' + (out?.conflicts_explained ?? []).length + ' explained with cited history). Review the evidence in the EMPI task before approving.';
const ok = reasons.length === 0;
const isNoop = typeof noop !== 'undefined' && noop === true;
const route = !ok ? 'escalate' : isNoop ? 'none' : 'approve';
return { json: { business_key: req.business_key, route, guardrail_reasons: reasons, action, approval_summary: summary, planned_actions: ok && !isNoop ? [action] : [] } };

// The approval request goes to one named person, so the approver is that person.
// Slack returns { data: { approved, respondedAt } }; a timeout resumes without it.
const cfg = $('Config').first().json;
const approved = $json.data?.approved;
return {
  json: {
    decision: approved === true ? 'approved' : approved === false ? 'declined' : 'timed_out',
    approver: cfg.approver_slack_user,
    decided_at: $json.data?.respondedAt ?? new Date().toISOString(),
    handoff_reason: approved === true || approved === false ? '' : 'approval timed out after ' + cfg.approval_timeout_hours + ' hours',
  },
};

// Done only when the system of record shows what was planned.
const planned = $('Guardrails').item.json.action;
const ok = $json.status === 'merged' && $json.merged_into === planned.survivor_id;
const detail = 'record ' + planned.retired_id + ' shows status ' + $json.status + ', merged into ' + ($json.merged_into ?? 'nothing') + ', expected ' + planned.survivor_id;
return { json: { verified: ok, verify_failed: !ok, verify_detail: ok ? '' : detail } };

// Collects everything a reviewer needs in one record: the request, what the agent
// proposed, why the guardrails stopped it, and the tool calls behind it.
const intake = $('Normalize match task').item.json;
let agent = null;
let guard = null;
try { agent = $('EMPI resolution agent').item.json; } catch (e) {}
try { guard = $('Guardrails').item.json; } catch (e) {}

const reasons = [...(guard?.guardrail_reasons ?? [])];
if ($json.error) reasons.push('system_error: ' + ($json.error.message ?? JSON.stringify($json.error)).slice(0, 300));
if ($json.verify_failed) reasons.push('verification_failed: ' + $json.verify_detail);
if ($json.handoff_reason) reasons.push($json.handoff_reason);
if (!agent?.output && !reasons.length) reasons.push('agent_produced_no_valid_output');
if (!reasons.length) {
  const o = agent.output;
  reasons.push('agent recommends review: ' + (o.decision ?? o.recommended_action ?? o.classification ?? o.route_to_queue ?? 'see proposal'));
}

const trace = (agent?.intermediateSteps ?? []).map((s) => ({
  tool: s.action?.tool,
  input: s.action?.toolInput,
  observation: String(s.observation ?? '').slice(0, 1500),
}));

return {
  json: {
    business_key: intake.business_key,
    team: "HIM data integrity",
    reasons,
    proposed: agent?.output ?? null,
    confidence: agent?.output?.confidence ?? null,
    questions: agent?.output?.questions_for_human ?? [],
    trace,
    summary: 'EMPI task ' + intake.task_id + ' · ' + intake.record_a + ' / ' + intake.record_b + ' · ' + (agent?.output?.decision ?? 'no decision'),
  },
};

parameters.query:
INSERT INTO agent_exceptions (workflow, business_key, team, reasons, proposed_action, confidence, questions, trace, summary, n8n_execution_id)
VALUES ($1, $2, $3, $4::jsonb, $5::jsonb, $6, $7::jsonb, $8::jsonb, $9, $10)
RETURNING id;

parameters.jsCode:
const intake = $('Normalize match task').item.json;
let agent = null;
let guard = null;
let approval = null;
try { agent = $('EMPI resolution agent').item.json; } catch (e) {}
try { guard = $('Guardrails').item.json; } catch (e) {}
// Present only on workflows with a named-approver step, and only if this run reached it.
try { approval = $('Record approval').item.json; } catch (e) {}

return {
  json: {
    business_key: intake.business_key,
    outcome: $json.outcome,
    approval: approval ? { decision: approval.decision, approver: approval.approver, decided_at: approval.decided_at } : null,
    route: guard?.route ?? 'escalate',
    decision: agent?.output ?? null,
    guardrail_reasons: guard?.guardrail_reasons ?? [],
    actions: guard?.planned_actions ?? [],
    tool_calls: (agent?.intermediateSteps ?? []).length,
  },
};
